width:25px;height:49px;clip-path:polygon(50% 0,100% 100%,0 100%);background:#715b40}.tent-one{right:13%;transform:scale(.88)}.tent-two{left:10%;bottom:24%;transform:scale(.63);background:#9e7654}.pine{position:absolute;width:100px;height:230px;bottom:11%;background:#243d33;clip-path:polygon(50% 0,63% 20%,57% 20%,76% 43%,67% 43%,94% 69%,60% 66%,72% 86%,50% 80%,27% 86%,40% 66%,7% 69%,33% 43%,24% 43%,44% 20%,37% 20%)}.pine:after{content:'';position:absolute;width:14px;height:70px;bottom:0;left:43px;background:#4f4938}.pine-a{left:3%;height:270px}.pine-b{left:34%;height:160px;transform:scale(.8);opacity:.8}.pine-c{right:2%;height:300px;transform:scale(1.1)}.campfire{position:absolute;bottom:14%;left:50%;width:30px;height:42px;z-index:2}.campfire i,.campfire b,.campfire span{position:absolute;bottom:0;left:8px;width:15px;height:30px;background:#f5a34d;border-radius:60% 0 60% 60%;transform:rotate(15deg);box-shadow:0 0 22px #ef9a48}.campfire b{left:5px;height:21px;background:#dc5540;transform:rotate(-25deg)}.campfire span{left:11px;height:17px;width:9px;background:#fce5a4}.hero-person{position:absolute;bottom:8%;left:48%;height:205px;width:115px;z-index:3}.hero-head{position:absolute;top:0;left:42px;width:45px;height:52px;background:#aa7655;border-radius:45% 45% 42% 42%;z-index:3}.hero-body{position:absolute;left:24px;top:45px;width:80px;height:110px;background:#b75f3e;border-radius:32px 32px 15px 15px;clip-path:polygon(25% 0,75% 0,100% 100%,0 100%)}.hero-arm{position:absolute;top:58px;left:5px;width:34px;height:85px;background:#aa7655;border-radius:20px;transform:rotate(17deg)}.art-label{position:absolute;bottom:25px;left:26px;color:#f3ecdb;font-size:9px;letter-spacing:2px;font-weight:700}.title-content{padding:9% 12% 6% 10%;align-self:center}.eyebrow{color:#8f6941;margin-bottom:19px}.title-content h1{font-family:'Playfair Display',serif;font-size:clamp(54px,7vw,87px);letter-spacing:-4px;line-height:.92;margin:0;color:#1c352b}.title-content h1 em{font-weight:600;color:#bb