ay:block;margin-bottom:9px}.activity-card strong{display:block;font:600 16px 'Playfair Display',serif;color:#274034}.activity-card small{display:block;font-size:10px;color:#82887d;margin-top:4px}.activity-card .arrow{position:absolute;right:13px;top:14px;color:#bd9154}.character-strip{border-top:1px solid var(--line);padding-top:13px;display:flex;gap:10px;align-items:center}.strip-label{font-size:8px;letter-spacing:1px;color:#92958a;margin-right:2px}.person-chip{display:flex;align-items:center;gap:7px;font-size:9px;color:#69736a}.mini-portrait{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;color:#fff;font-size:9px;font-weight:700;background:#9b6045}.mini-portrait.dax{background:#627a68}.mini-portrait.malik{background:#976f48}.person-chip b{font-weight:600}.game-footer{height:43px;display:flex;align-items:center;justify-content:space-between;padding:0 4.3%;font-size:8px;letter-spacing:1.4px;color:#999a91;border-top:1px solid var(--line);flex-shrink:0}.game-footer b{color:#55705b}.game-footer button{border:0;background:transparent;color:#9b9d93;font-size:8px;letter-spacing:1px}.game-footer button:hover{color:#425b4b}

