const cast = {
  rafi: {name:'Rafi Pratama', age:32, role:'Kepala instruktur · pendaki yang tenang', color:'rafi', initials:'R'},
  dax: {name:'Dax Mahendra', age:36, role:'Pelatih kebugaran · hati selembut api unggun', color:'dax', initials:'D'},
  malik: {name:'Malik Hidayat', age:30, role:'Koki kemah · senyum paling mudah menular', color:'malik', initials:'M'}
};
const activities = [
  {id:'rafi', icon:'⌁', title:'Jalur Punggung Bukit', subtitle:'Temani Rafi memeriksa jalur', place:'JALUR PUNGGUNG BUKIT', day:1, titleText:'Langkah yang seirama', intro:'Kabut pagi belum sepenuhnya terangkat saat Rafi menyodorkan termos. Ia berusia 32, bahunya lebar, suaranya tenang—dan ia menunggumu menyamakan langkah sebelum mulai mendaki.', speaker:'RAFI', char:'rafi', options:[['Aku ikut ritmemu. Tunjukkan jalan.','steady'],['Kau selalu setenang ini saat memimpin?','warm']]},
  {id:'dax', icon:'✦', title:'Belah Kayu', subtitle:'Bantu Dax menyiapkan api unggun', place:'GUDANG KAYU', day:1, titleText:'Tenaga dan tawa', intro:'Dax, 36, baru selesai memindahkan seikat kayu seolah beratnya tak seberapa. Ia menyodorkan kapak dengan senyum menantang, tapi langsung memastikan kamu tahu cara memegangnya dengan aman.', speaker:'DAX', char:'dax', options:[['Ajari aku teknik yang benar dulu.','steady'],['Kalau kau terus pamer, aku jadi penasaran.','warm']]},
  {id:'malik', icon:'❋', title:'Dapur Terbuka', subtitle:'Masak sarapan bersama Malik', place:'DAPUR TERBUKA', day:1, titleText:'Resep rahasia', intro:'Aroma kopi dan roti panggang memenuhi dapur. Malik, 30, menggulung lengan kemejanya dan menawari tempat di sampingnya—cukup dekat untuk berbagi talenan.', speaker:'MALIK', char:'malik', options:[['Biar aku yang memotong. Apa resep andalanmu?','warm'],['Kau masak, aku jadi pencicip resmi.','playful']]},
  {id:'rafi', icon:'⌁', title:'Menyusuri Danau', subtitle:'Cari sudut pandang rahasia bersama Rafi', place:'TEPI DANAU PINUS', day:2, titleText:'Di balik peta', intro:'Rafi menemukan sebuah teluk kecil di ujung dermaga. Saat kalian berhenti, ia bercerita bahwa ia dulu datang ke kemah ini untuk menghindari keramaian—sebelum akhirnya memilih tinggal.', speaker:'RAFI', char:'rafi', options:[['Terima kasih sudah mempercayakan cerita itu padaku.','warm'],['Kadang tempat tenang memang membantu kita jujur.','steady']]},
  {id:'dax', icon:'✦', title:'Latihan Pagi', subtitle:'Latihan ringan, tanpa adu ego', place:'LAPANGAN KEMAH', day:2, titleText:'Kuat bukan berarti sendiri', intro:'Dax mengajakmu melakukan peregangan di lapangan. Di sela hitungan, ia mengaku dulu mengira meminta bantuan adalah tanda lemah. “Ternyata cuma bikin semua lebih berat,” katanya sambil terkekeh.', speaker:'DAX', char:'dax', options:[['Aku suka caramu bicara soal kekuatan.','warm'],['Kalau begitu, biar aku yang hitung repetisimu.','playful']]},
  {id:'malik', icon:'❋', title:'Bekal Piknik', subtitle:'Bikin bekal untuk perjalanan sore', place:'DAPUR TERBUKA', day:2, titleText:'Hal kecil yang diingat', intro:'Malik hafal siapa yang suka kopi pahit, siapa yang alergi kacang, bahkan cara tiap orang memesan teh. Ia mengangkat bahu saat kamu memujinya. “Memperhatikan itu gampang kalau kita peduli.”', speaker:'MALIK', char:'malik', options:[['Kau membuat semua orang merasa diperhatikan.','warm'],['Apa ada yang memperhatikanmu juga?','deep']]},
  {id:'rafi', icon:'⌁', title:'Menara Pandang', subtitle:'Berbagi langit senja bersama Rafi', place:'MENARA PANDANG', day:3, titleText:'Peta baru', intro:'Senja mewarnai hutan tembaga. Rafi membuka peta lama, lalu menggeser duduknya agar bahu kalian bersentuhan. Besok pagi kamu akan pulang—dan ia tak ingin membiarkan kesempatan ini lewat begitu saja.', speaker:'RAFI', char:'rafi', options:[['Kita bisa merencanakan pendakian berikutnya. Bersama.','commit'],['Aku senang menemukan seseorang yang bisa diam bersamaku.','deep']]},
  {id:'dax', icon:'✦', title:'Api Unggun Terakhir', subtitle:'Dax menyimpan tempat untukmu', place:'LINGKAR API UNGGUN', day:3, titleText:'Bara yang bertahan', intro:'Api unggun tinggal bara merah. Dax duduk di sampingmu, tanpa lelucon atau tantangan kali ini. “Aku senang kamu datang,” katanya. “Aku juga berharap ini bukan cuma cerita tiga hari.”', speaker:'DAX', char:'dax', options:[['Aku juga ingin mencari tahu ke mana ini berjalan.','commit'],['Boleh kita mulai dengan sarapan bersama minggu depan?','warm']]},
  {id:'malik', icon:'❋', title:'Makan Malam Perpisahan', subtitle:'Malik menyiapkan satu meja untuk berdua', place:'DAPUR TERBUKA', day:3, titleText:'Bukan resep terakhir', intro:'Malik menyelipkan kartu kecil di bawah cangkir tehmu. Bukan resep—nomor teleponnya. “Aku bisa masak untuk dua orang di kota,” katanya, pipinya memerah tipis.', speaker:'MALIK', char:'malik', options:[['Aku akan menagih makan malam itu.','commit'],['Aku suka tawaran yang disertai makanan.','playful']]}
];
const state={day:1, bonds:{rafi:0,dax:0,malik:0}, resolve:0, selected:null, muted:false, started:false};
const $=s=>document.querySelector(s);
const titleScreen=$('#title-screen'), gameScreen=$('#game-screen'), content=$('#content-area');
function playTone(freq=520){if(state.muted)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)(),o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.035,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);o.start();o.stop(ctx.currentTime+.13);o.onended=()=>ctx.close()}catch(e){}}
function setHeader(title,kicker=`HARI ${String(state.day).padStart(2,'0')} · ${['PAGI','SIANG','SENJA'][state.day-1]}`){$('#chapter-title').textContent=title;$('#chapter-kicker').textContent=kicker;$('#footer-day').textContent=String(state.day).padStart(2,'0');document.querySelectorAll('.progress-dots i').forEach((el,i)=>el.classList.toggle('active',i<state.day))}
function renderStrip(){const strip=$('#character-strip');strip.innerHTML='<span class="strip-label">KENALANMU</span>'+Object.entries(cast).map(([id,c])=>`<div class="person-chip"><span class="mini-portrait ${c.color}">${c.initials}</span><b>${c.name.split(' ')[0]}</b><span>♥ ${state.bonds[id]}</span></div>`).join('')}
function renderScene(char,place){const el=$('#scene-character');el.className=`scene-character character-${char}`;const c=cast[char];if(char==='dax'){el.style.setProperty('--skin','#b77e5d');el.querySelector('.char-torso').style.background='#526e5a';el.querySelector('.hair').style.background='#514439';el.querySelector('.beard').style.background='#58483b'}else if(char==='malik'){el.style.setProperty('--skin','#9a6849');el.querySelector('.char-torso').style.background='#9d7946';el.querySelector('.hair').style.background='#262a27';el.querySelector('.beard').style.background='#262a27'}else{el.style.setProperty('--skin','#a97555');el.querySelector('.char-torso').style.background='#9c593c';el.querySelector('.hair').style.background='#38332d';el.querySelector('.beard').style.background='#3c352e'}$('#scene-caption-text').textContent=place||'POS PENJAGAAN · DANAU PINUS'}
function intro(){setHeader('Kedatangan');renderScene('rafi','POS PENJAGAAN · DANAU PINUS');content.innerHTML=`<p class="scene-eyebrow">SELAMAT DATANG DI KEMAH PINE & IRON</p><h2 class="story-title">Tiga hari untuk<br>menemukan arah.</h2><p class="story-text">Kamu tiba di kemah tepi danau untuk membantu persiapan festival akhir musim. Para instruktur di sini bukan sekadar kuat—mereka punya cerita, kebiasaan, dan ruang untuk seseorang yang mau benar-benar hadir.</p><div class="speaker-line"><span class="speaker-name">PILIH CARA MEMULAI</span><i class="speaker-rule"></i></div><div class="choices"><button class="choice-button" data-action="activities">Aku ingin menjelajahi kemah <span>→</span></button><button class="choice-button" data-action="journal">Kenali para instruktur dulu <span>→</span></button></div>`;}
function showActivities(){state.selected=null;setHeader(state.day===1?'Hari pertama':'Hari '+['','pertama','kedua','ketiga'][state.day]);renderScene('rafi',state.day===1?'POS PENJAGAAN · DANAU PINUS':'KEMAH PINE & IRON');const today=activities.filter(a=>a.day===state.day);const title=state.day===1?'Pilih langkah pertamamu':state.day===2?'Hari kedua, pilih temanmu':'Malam terakhir';const introText=state.day===1?'Kemah masih asing, tapi pilihan kecil bisa membuka percakapan besar. Siapa yang ingin kamu temui lebih dulu?':state.day===2?'Setelah hari pertama yang panjang, kamu mulai merasa seperti bagian dari kemah. Luangkan waktu dengan seseorang yang membuatmu penasaran.':'Besok pagi kamu pulang. Pilih satu momen terakhir untuk dibagikan.';content.innerHTML=`<p class="scene-eyebrow">${state.day===1?'HARI PERTAMA · PAGI':state.day===2?'HARI KEDUA · SIANG':'HARI KETIGA · SENJA'}</p><h2 class="story-title">${title}</h2><p class="story-text">${introText}</p><div class="activity-grid">${today.map((a,i)=>`<button class="activity-card" data-activity="${a.id}"><span class="activity-icon">${a.icon}</span><strong>${a.title}</strong><small>${a.subtitle}</small><span class="arrow">↗</span></button>`).join('')}</div>`;}
function showActivity(id){const a=activities.find(x=>x.day===state.day&&x.id===id);if(!a)return;state.selected=a;setHeader(a.title,`HARI ${String(state.day).padStart(2,'0')} · ${state.day===3?'SENJA':'SIANG'}`);renderScene(a.char,a.place);content.innerHTML=`<p class="scene-eyebrow">${state.day===1?'MOMEN PERTAMA':state.day===2?'WAKTU BERSAMA':'MALAM TERAKHIR'}</p><h2 class="story-title">${a.titleText}</h2><p class="story-text">${a.intro}</p><div class="speaker-line"><span class="speaker-name">${a.speaker} · ${cast[a.char].age} TAHUN</span><i class="speaker-rule"></i></div><div class="choices">${a.options.map((o,i)=>`<button class="choice-button" data-choice="${i}">${o[0]} <span>→</span></button>`).join('')}</div>`;}
function answer(index){const a=state.selected;if(!a)return;const [line,tone]=a.options[index];const gain=tone==='commit'?3:tone==='deep'?2:tone==='warm'?2:1;state.bonds[a.id]=Math.min(9,state.bonds[a.id]+gain);state.resolve+=tone==='steady'||tone==='deep'?1:0;playTone(640);renderStrip();const replies={rafi:['Rafi tersenyum kecil. “Bagus. Aku suka orang yang tahu kapan harus mengikuti jalur—dan kapan harus bertanya.”','Ia menatap danau, lalu kembali menatapmu. “Aku jarang cerita seperti itu. Rasanya tepat kalau denganmu.”'],dax:['Dax tertawa lepas. “Deal. Tapi jangan salahkan aku kalau hitunganku bikin kamu minta jeda.”','Senyumnya melunak. “Kau tahu, tidak banyak orang yang menanyakan itu. Terima kasih.”'],malik:['Malik tertawa, lalu menyenggol bahumu pelan. “Pencicip resmi harus datang lagi besok. Itu aturan dapur.”','Senyum Malik menghangat. “Kalau kamu di sini, aku rasa aku tak perlu repot mencarinya.”']};let reply=replies[a.id][(tone==='deep'||tone==='commit')?1:0];if(a.day===3)reply+=' Saat api mulai padam, kalian bertukar kontak dan berjanji untuk bertemu lagi setelah musim kemah usai.';content.innerHTML=`<p class="scene-eyebrow">${a.speaker} · MENANGGAPI</p><h2 class="story-title">${a.speaker==='DAX'?'Tawa yang tulus':a.speaker==='MALIK'?'Senyum yang tinggal':'Jeda yang nyaman'}</h2><p class="story-text">${reply}</p><div class="bond-note"><span>♥</span> Hubunganmu dengan ${cast[a.id].name.split(' ')[0]} semakin dekat.</div><div class="choices"><button class="choice-button" data-action="continue">${state.day<3?'Lanjutkan hari':'Lihat bagaimana kisahmu berakhir'} <span>→</span></button></div>`;}
function ending(){const winner=Object.keys(state.bonds).sort((a,b)=>state.bonds[b]-state.bonds[a])[0];const c=cast[winner];const endings={rafi:{title:'Jalan yang kalian pilih',text:'Pagi datang bersama kabut tipis. Rafi mengantarmu sampai gerbang, peta pendakian terbuka di antara kalian. “Bulan depan?” tanyanya. Kamu mengangguk—beberapa perjalanan memang terasa lebih baik jika ditempuh berdua.'},dax:{title:'Lebih dari sekadar kuat',text:'Dax memelukmu erat sebelum kendaraanmu berangkat. Ia menyelipkan catatan latihan dengan nomor telepon di baliknya. Bukan tantangan kali ini, hanya janji untuk bertemu lagi—dan mungkin sarapan setelahnya.'},malik:{title:'Rasa yang ingin diulang',text:'Malik membawakan bekal untuk perjalanan pulang, lengkap dengan resep yang ia tulis tangan. Di bawahnya ada pesan singkat: “Makan malam berikutnya di kota?” Kamu menyimpan catatan itu baik-baik.'}};const e=endings[winner];setHeader('Akhir cerita','PINE & IRON · EPILOG');renderScene(winner,'GERBANG KEMAH · PAGI');content.innerHTML=`<p class="scene-eyebrow">AKHIR YANG KAMU PILIH</p><span class="ending-stamp">✦ IKATAN TERDALAM · ${c.name.toUpperCase()}</span><h2 class="story-title" style="margin-top:14px">${e.title}</h2><p class="story-text">${e.text}</p><div class="final-score"><div><small>IKATAN DENGAN ${c.name.split(' ')[0].toUpperCase()}</small><strong>♥ ${state.bonds[winner]} · 9</strong></div><div><small>KEBERANIANMU</small><strong>✦ ${state.resolve}</strong></div></div><p class="story-text">Terima kasih sudah menghabiskan musim panas di Pine & Iron. Cerita bisa berubah setiap kali kamu memilih jalan yang berbeda.</p><div class="choices"><button class="choice-button" data-action="restart">Mainkan lagi dengan pilihan baru <span>↻</span></button></div>`;}
function continueGame(){if(state.day<3){state.day++;showActivities()}else ending()}
function showJournal(){const rows=Object.entries(cast).map(([id,c])=>`<div class="journal-person"><span class="mini-portrait ${c.color}">${c.initials}</span><div><strong>${c.name} · ${c.age}</strong><small>${c.role}</small></div><span class="bond-value">♥ ${state.bonds[id]}</span></div>`).join('');$('#modal-root').innerHTML=`<div class="modal-backdrop" data-close="1"><section class="modal-card" role="dialog" aria-modal="true" aria-label="Jurnal perjalanan"><button class="modal-close" data-close="1" aria-label="Tutup">×</button><p class="scene-eyebrow">CATATAN PERJALANAN · HARI ${state.day}</p><h2>Jurnal Kemah</h2><p>Semua yang kamu temui di sini adalah pria dewasa, masing-masing dengan cara sendiri untuk menunjukkan perhatian. Kedekatan tumbuh dari waktu, rasa ingin tahu, dan pilihanmu.</p>${rows}<p style="font-size:10px;margin-bottom:0">Keberanian: <b>${state.resolve}</b> · Momen yang dibagikan: <b>${Object.values(state.bonds).reduce((a,b)=>a+b,0)}</b></p></section></div>`;}
function reset(){state.day=1;state.bonds={rafi:0,dax:0,malik:0};state.resolve=0;state.selected=null;intro();renderStrip();}
document.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(target.dataset.action==='activities'){playTone();showActivities()}else if(target.dataset.action==='journal'){playTone();showJournal()}else if(target.dataset.action==='continue'){playTone();continueGame()}else if(target.dataset.action==='restart'){playTone();reset()}else if(target.dataset.activity){playTone();showActivity(target.dataset.activity)}else if(target.dataset.choice!==undefined){answer(Number(target.dataset.choice))}else if(target.dataset.close){$('#modal-root').innerHTML=''}});
$('#start-btn').addEventListener('click',()=>{playTone();state.started=true;titleScreen.classList.add('hidden');gameScreen.classList.remove('hidden');reset()});$('#journal-btn').addEventListener('click',showJournal);$('#restart-btn').addEventListener('click',()=>{if(confirm('Mulai ulang cerita dari hari pertama?'))reset()});$('#sound-btn').addEventListener('click',e=>{state.muted=!state.muted;e.currentTarget.textContent=state.muted?'♫̸':'♫';e.currentTarget.setAttribute('aria-label',state.muted?'Aktifkan efek suara':'Matikan efek suara');if(!state.muted)playTone()});

