 :root{--ink:#172820;--forest:#18352b;--forest2:#23473a;--cream:#f4efe4;--paper:#fbf8f1;--gold:#d8aa62;--muted:#758078;--line:#e4dfd4;--rust:#bb6d49}
 *{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#101d18;color:var(--ink);font-family:'DM Sans',sans-serif}button{font:inherit;cursor:pointer}button:focus-visible{outline:3px solid #d5a659;outline-offset:3px}.hidden{display:none!important}.app-shell{min-height:100vh;background:#14251f;display:flex;justify-content:center;align-items:center;padding:24px}
 .title-screen{width:min(1200px,100%);min-height:min(750px,calc(100vh - 48px));background:var(--cream);position:relative;overflow:hidden;display:grid;grid-template-columns:52% 48%;grid-template-rows:72px 1fr 54px;box-shadow:0 28px 80px #07120e88}.title-top{grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;padding:0 5.4%;z-index:2;border-bottom:1px solid #d8d1c3}.brand-mark,.wordmark{font-family:'Playfair Display',serif;font-weight:800;font-size:23px;letter-spacing:-2px;color:var(--forest)}.brand-mark span,.wordmark span{font-size:12px;color:#b4843e;margin:0 3px}.edition,.eyebrow,.mini-label{font-size:9px;font-weight:700;letter-spacing:1.75px;color:#737b70}.title-art{position:relative;overflow:hidden;min-height:550px;background:linear-gradient(180deg,#c7d9d3 0%,#e6d9bb 49%,#536c60 50%,#28463d 100%)}.sun{position:absolute;width:118px;height:118px;border-radius:100%;background:#eed4a0;top:15%;right:19%;box-shadow:0 0 70px #f7dfa674}.ridge{position:absolute;bottom:32%;width:115%;height:43%;background:#789188;clip-path:polygon(0 100%,0 70%,13% 48%,24% 69%,42% 15%,57% 64%,72% 31%,89% 72%,100% 42%,100% 100%)}.ridge-back{background:#a2b3a5;bottom:34%;opacity:.8;transform:scaleX(-1)}.ridge-front{background:#516e60;bottom:25%;clip-path:polygon(0 100%,0 72%,19% 34%,31% 66%,51% 25%,67% 71%,82% 45%,100% 67%,100% 100%)}.lake{position:absolute;left:0;right:0;bottom:0;height:35%;background:linear-gradient(180deg,#718c7d,#314d43)}.lake:before{content:'';position:absolute;left:14%;right:18%;top:20%;height:2px;background:#d1c7a2;opacity:.65;box-shadow:55px 15px 0 #d1c7a2,140px -5px 0 #d1c7a2,255px 24px 0 #d1c7a2}.dock{position:absolute;bottom:19%;left:58%;width:27%;height:8px;background:#92744f;transform:skewY(-7deg);box-shadow:0 7px 0 #715d43}.tent{position:absolute;bottom:20%;width:125px;height:95px;clip-path:polygon(50% 0,100% 100%,0 100%);background:#d7ad70;filter:drop-shadow(4px 7px 0 #403e30)}.tent:after{content:'';position:absolute;left:47%;bottom:0;width:25px;height:49px;clip-path:polygon(50% 0,100% 100%,0 100%);background:#715b40}.tent-one{right:13%;transform:scale(.88)}.tent-two{left:10%;bottom:24%;transform:scale(.63);background:#9e7654}.pine{position:absolute;width:100px;height:230px;bottom:11%;background:#243d33;clip-path:polygon(50% 0,63% 20%,57% 20%,76% 43%,67% 43%,94% 69%,60% 66%,72% 86%,50% 80%,27% 86%,40% 66%,7% 69%,33% 43%,24% 43%,44% 20%,37% 20%)}.pine:after{content:'';position:absolute;width:14px;height:70px;bottom:0;left:43px;background:#4f4938}.pine-a{left:3%;height:270px}.pine-b{left:34%;height:160px;transform:scale(.8);opacity:.8}.pine-c{right:2%;height:300px;transform:scale(1.1)}.campfire{position:absolute;bottom:14%;left:50%;width:30px;height:42px;z-index:2}.campfire i,.campfire b,.campfire span{position:absolute;bottom:0;left:8px;width:15px;height:30px;background:#f5a34d;border-radius:60% 0 60% 60%;transform:rotate(15deg);box-shadow:0 0 22px #ef9a48}.campfire b{left:5px;height:21px;background:#dc5540;transform:rotate(-25deg)}.campfire span{left:11px;height:17px;width:9px;background:#fce5a4}.hero-person{position:absolute;bottom:8%;left:48%;height:205px;width:115px;z-index:3}.hero-head{position:absolute;top:0;left:42px;width:45px;height:52px;background:#aa7655;border-radius:45% 45% 42% 42%;z-index:3}.hero-body{position:absolute;left:24px;top:45px;width:80px;height:110px;background:#b75f3e;border-radius:32px 32px 15px 15px;clip-path:polygon(25% 0,75% 0,100% 100%,0 100%)}.hero-arm{position:absolute;top:58px;left:5px;width:34px;height:85px;background:#aa7655;border-radius:20px;transform:rotate(17deg)}.art-label{position:absolute;bottom:25px;left:26px;color:#f3ecdb;font-size:9px;letter-spacing:2px;font-weight:700}.title-content{padding:9% 12% 6% 10%;align-self:center}.eyebrow{color:#8f6941;margin-bottom:19px}.title-content h1{font-family:'Playfair Display',serif;font-size:clamp(54px,7vw,87px);letter-spacing:-4px;line-height:.92;margin:0;color:#1c352b}.title-content h1 em{font-weight:600;color:#bb8a4c}.title-sub{font-family:'Playfair Display',serif;font-style:italic;font-size:24px;color:#8e7554;margin:13px 0 26px}.title-copy{font-size:14px;line-height:1.8;color:#606960;max-width:380px;margin:0 0 26px}.button{border:0}.button-gold{background:#1d3b30;color:#f8f3e8;padding:17px 22px;font-size:10px;font-weight:700;letter-spacing:1.2px;box-shadow:4px 4px 0 #d8aa62;transition:.2s}.button-gold:hover{background:#2c5243;transform:translate(1px,1px);box-shadow:3px 3px 0 #d8aa62}.button-gold span{font-size:15px;margin-left:19px;color:#e3ba78}.adult-note{font-size:10px;color:#84877e;margin-top:24px}.title-footer{grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;padding:0 5.4%;font-size:8px;letter-spacing:1.5px;color:#8a8b80;border-top:1px solid #d8d1c3}
 .game-screen{width:min(1240px,100%);min-height:min(790px,calc(100vh - 40px));background:var(--paper);box-shadow:0 28px 80px #07120e88;display:flex;flex-direction:column;position:relative}.topbar{height:72px;padding:0 4.2%;display:flex;align-items:center;border-bottom:1px solid var(--line);gap:22px;flex-shrink:0}.wordmark{font-size:21px;text-decoration:none}.chapter-label{border-left:1px solid var(--line);padding-left:20px;display:flex;flex-direction:column;gap:3px}.chapter-label span{font-size:8px;font-weight:700;letter-spacing:1.5px;color:#a27c49}.chapter-label strong{font-family:'Playfair Display',serif;font-size:16px;color:#274033}.top-actions{margin-left:auto;display:flex;gap:8px}.icon-button{width:34px;height:34px;border:1px solid var(--line);background:transparent;color:#536458;font-size:16px}.icon-button:hover{background:#ece7dc}.game-layout{display:grid;grid-template-columns:48% 52%;flex:1;min-height:590px}.scene-panel{padding:25px 0 22px 6%;display:flex;flex-direction:column;min-height:0}.scene-sky{position:relative;flex:1;min-height:475px;overflow:hidden;background:linear-gradient(#bfd0c5 0%,#e6d9bc 48%,#718778 49%,#526e60 100%)}.scene-sun{position:absolute;top:12%;right:15%;width:76px;height:76px;border-radius:50%;background:#eed5a3;box-shadow:0 0 38px #f3daa66b}.scene-mountain{position:absolute;left:-5%;bottom:38%;width:112%;height:33%;background:#8da397;clip-path:polygon(0 100%,0 69%,18% 32%,32% 73%,52% 11%,67% 67%,83% 30%,100% 72%,100% 100%)}.m2{background:#647f72;bottom:31%;transform:scaleX(-1);opacity:.9}.scene-treeline{position:absolute;left:0;right:0;bottom:37%;height:18%;background:#355448;clip-path:polygon(0 62%,5% 25%,10% 66%,16% 12%,24% 68%,31% 21%,39% 72%,48% 10%,55% 66%,66% 19%,74% 70%,85% 13%,92% 61%,100% 20%,100% 100%,0 100%)}.scene-water{position:absolute;left:0;right:0;bottom:0;height:36%;background:linear-gradient(#768f7f,#3e5e50)}.scene-water:after{content:'';position:absolute;left:15%;top:25%;width:65%;height:2px;background:#d1c49c;opacity:.6;box-shadow:75px 14px 0 #d1c49c,180px -9px 0 #d1c49c}.scene-shore{position:absolute;left:-10%;bottom:28%;height:14%;width:125%;border-radius:50%;background:#8b8869;transform:rotate(-2deg)}.scene-tent{position:absolute;right:9%;bottom:24%;height:72px;width:83px;background:#d5a966;clip-path:polygon(50% 0,100% 100%,0 100%);z-index:1}.scene-tent i{position:absolute;left:40%;bottom:0;width:23px;height:38px;background:#766145;clip-path:polygon(50% 0,100% 100%,0 100%)}.scene-tree{position:absolute;bottom:24%;width:70px;height:200px;background:#203d31;clip-path:polygon(50% 0,68% 28%,60% 28%,84% 54%,68% 54%,100% 80%,60% 76%,72% 100%,27% 100%,40% 76%,0 80%,32% 54%,16% 54%,40% 28%,32% 28%);z-index:2}.tree1{left:0;height:235px}.tree2{left:22%;height:145px;transform:scale(.75);opacity:.9}.tree3{right:-2%;height:247px;transform:scale(1.1)}

